use std::collections::HashMap; fn main() { let mut m = HashMap::new(); for x in [3, 1, 3, 2, 3, 1] { *m.entry(x).or_insert(0) += 1; } let mut k: Vec<_> = m.iter().collect(); k.sort(); println!("{:?}", k); let mut n: HashMap<String, i64> = HashMap::new(); for w in "b a b".split(" ") { n.insert(w.to_string(), w.len() as i64); } let mut p: Vec<_> = n.iter().collect(); p.sort(); println!("{:?} {}", p, n.len()); }
